const e=JSON.parse(`[{"id":"b2_listening_dialogues_10x3","title":"MET B2 Listening — 10 Conversations × 3 Questions","skill":"listening","levelRange":"B2","moduleType":"listening_set","items":[{"id":"listen_01_cafe","audioFile":"listening-L01-cafe-oat-milk.wav","script":"N: Listen to a conversation in a coffee shop.\\nBarista: Hi, what can I get for you?\\nCustomer: I’d like a large latte, please — with oat milk if you have it.\\nBarista: We do, but I should mention we’re out of oat milk until the delivery arrives around two.\\nCustomer: Oh, I have a dairy allergy, so I can’t have regular milk. What time is your delivery usually?\\nBarista: Usually by two, but the driver called and said maybe three today because of traffic on Main Street.\\nCustomer: I have a meeting at two-thirty nearby. Could I come back after that?\\nBarista: That should work. I can set one aside for you if you’d like.\\nN: Now answer the questions.","questions":[{"stem":"Why can’t the customer order a latte right now?","options":["The shop is closing early.","The customer doesn’t have enough money.","The shop is temporarily out of oat milk.","The barista doesn’t know how to make it."],"correct":2,"explanation":"The barista says they are out of oat milk until the delivery around two/three, and the customer needs oat milk due to a dairy allergy."},{"stem":"What does the barista offer to do?","options":["Give the customer a discount.","Reserve a latte for later.","Deliver the drink to the meeting.","Call another coffee shop."],"correct":1,"explanation":"Barista says 'I can set one aside for you' if the customer returns after the meeting."},{"stem":"What can be inferred about the delivery today?","options":["It will arrive earlier than usual.","It has been cancelled.","It is delayed because of traffic.","It will bring only regular milk."],"correct":2,"explanation":"The driver called and said maybe three today because of traffic on Main Street — later than the usual two o’clock."}]},{"id":"listen_02_advisor","audioFile":"listening-L02-academic-advisor.wav","script":"N: Listen to a conversation between a student and an academic advisor.\\nAdvisor: So, you’re thinking about taking Introduction to Marketing next term?\\nStudent: Yes, but the only open section is Tuesday evenings, and that’s when I work at the clinic.\\nAdvisor: There is an online section, but it fills quickly. If you want it, you should register today.\\nStudent: I was hoping for in-person because I learn better when I can ask questions directly.\\nAdvisor: I understand, but if your work schedule can’t change, the online option may be more practical.\\nStudent: True. I’ll call my manager this afternoon to see if I can switch shifts. If not, I’ll take the online class.\\nN: Now answer the questions.","questions":[{"stem":"Why is the student worried about the Marketing course?","options":["He has failed it before.","He cannot find the classroom.","The only available time conflicts with work.","The professor is too strict."],"correct":2,"explanation":"The only open in-person section is Tuesday evenings, when he works at the clinic."},{"stem":"What does the advisor suggest about the online section?","options":["It is easier than the in-person class.","It requires no registration.","It fills quickly and needs early registration.","It is only for advanced students."],"correct":2,"explanation":"Advisor says the online section fills quickly and the student should register today if he wants it."},{"stem":"What will the student probably do first?","options":["Drop the course completely.","Ask his manager about changing work hours.","Register for the online class immediately.","Talk to another professor."],"correct":1,"explanation":"He says he’ll call his manager this afternoon to see if he can switch shifts before deciding."}]},{"id":"listen_03_clinic","audioFile":"listening-L03-clinic-reception.wav","script":"N: Listen to a conversation at a clinic reception desk.\\nReceptionist: Good morning, how can I help you?\\nPatient: I had a blood test last Thursday, and I’m calling to ask if the results are ready.\\nReceptionist: Let me check. Yes, the doctor reviewed them this morning. She’d like you to come in tomorrow at ten to discuss them.\\nPatient: Is everything okay? Should I be worried?\\nReceptionist: The note just says she wants to explain the results in person. It doesn’t look urgent — otherwise she would have called you directly.\\nPatient: Okay, I’ll be there at ten. Do I need to bring anything?\\nReceptionist: Just your ID and a list of any medications you’re currently taking.\\nN: Now answer the questions.","questions":[{"stem":"Why does the doctor want to see the patient?","options":["To give an injection.","To explain the blood test results in person.","To cancel the patient’s insurance.","To collect payment."],"correct":1,"explanation":"The doctor reviewed the blood test and wants to discuss the results in person tomorrow at ten."},{"stem":"What does the receptionist imply about the results?","options":["They are very urgent.","They are probably not an emergency.","They were lost.","They need to be repeated."],"correct":1,"explanation":"She says it doesn’t look urgent — otherwise the doctor would have called directly."},{"stem":"What should the patient bring to the appointment?","options":["A family member.","Previous test results from another clinic.","ID and a list of current medications.","A referral letter."],"correct":2,"explanation":"Receptionist says to bring ID and a list of any medications currently being taken."}]},{"id":"listen_04_library","audioFile":"listening-L04-library-renewal.wav","script":"N: Listen to a conversation in a university library.\\nStudent: Hi, I need to renew a book, but I’ve already renewed it twice online.\\nLibrarian: Yes, after two online renewals you have to bring the book in so we can check its condition.\\nStudent: I have it here. I was hoping to keep it for another week because I’m finishing a research paper.\\nLibrarian: Let me see. There’s no hold on it from other students, so I can renew it for seven more days. After that, though, you’ll need to return it.\\nStudent: That’s perfect — my paper is due Friday.\\nN: Now answer the questions.","questions":[{"stem":"Why can’t the student renew the book online again?","options":["The library website is down.","He has already reached the online renewal limit.","The book is overdue.","He forgot his library password."],"correct":1,"explanation":"After two online renewals the book must be brought in to check its condition."},{"stem":"What condition allows another renewal?","options":["The student pays a small fee.","No other student has requested the book.","The book is newly published.","The librarian knows the student personally."],"correct":1,"explanation":"Librarian says there’s no hold from other students, so a seven-day renewal is possible."},{"stem":"What can be inferred about the student’s paper?","options":["It was already submitted last week.","He will need the book until close to the deadline.","He is writing it with a partner.","He plans to ask for an extension."],"correct":1,"explanation":"He says the seven days is perfect because the paper is due Friday — he needs the book until then."}]},{"id":"listen_05_train","audioFile":"listening-L05-train-delay.wav","script":"N: Listen to an announcement and a short conversation at a train station.\\nAnnouncer: Attention passengers on platform three. The 9:15 express to Riverview is delayed by approximately twenty minutes due to signal maintenance. Passengers who need to reach Riverview before ten should take the 9:30 local train on platform one, which will make all stops but arrive by 9:55.\\nWoman: Did you hear that? We’ll miss our connection if we wait.\\nMan: Let’s switch to the local. It’s slower, but we’ll still get there on time, and I’d rather not risk waiting.\\nWoman: Okay, let’s move to platform one now before it gets crowded.\\nN: Now answer the questions.","questions":[{"stem":"Why is the express train delayed?","options":["Bad weather.","Signal maintenance work.","A problem with the engine.","Too many passengers."],"correct":1,"explanation":"The announcement says the delay is due to signal maintenance."},{"stem":"What alternative does the announcer suggest?","options":["Taking a bus instead.","Waiting for the next express.","Taking the 9:30 local train on platform one.","Canceling the trip."],"correct":2,"explanation":"Passengers needing to arrive before ten should take the 9:30 local on platform one, arriving by 9:55."},{"stem":"What will the two passengers probably do?","options":["Wait on platform three for the express.","Go to platform one to catch the local.","Return home and travel tomorrow.","Ask for a refund."],"correct":1,"explanation":"They decide to switch to the local and move to platform one before it gets crowded."}]},{"id":"listen_06_housing","audioFile":"listening-L06-apartment-viewing.wav","script":"N: Listen to two roommates discussing an apartment.\\nWoman: I like the place on Green Street. It’s cheaper, and the kitchen was renovated last year.\\nMan: I liked it too, but it’s quite far from the train station, and the bedrooms are small — I’m not sure my desk would fit.\\nWoman: That’s true, though the bus stop is right outside, and internet is included in the rent, which saves money each month.\\nMan: Good point. Should we visit again and measure the rooms before deciding?\\nWoman: Yes, let’s go again on Friday and bring a tape measure.\\nN: Now answer the questions.","questions":[{"stem":"What does the woman like about the apartment?","options":["It is close to the train station and has large bedrooms.","It is cheaper and has a nicer kitchen.","It includes free furniture.","It has a private garden."],"correct":1,"explanation":"She says it’s cheaper and the kitchen was renovated."},{"stem":"What is the man’s main concern?","options":["The apartment is too expensive.","The location is far and bedrooms are small.","The kitchen is too old.","The bus stop is too noisy."],"correct":1,"explanation":"He notes it’s far from the train and the bedrooms are small for his desk."},{"stem":"What do they decide to do?","options":["Sign the contract today.","Visit the apartment again on Friday to measure.","Look for a different apartment immediately.","Ask a third roommate to decide."],"correct":1,"explanation":"They agree to visit again on Friday and bring a tape measure."}]},{"id":"listen_07_museum","audioFile":"listening-L07-museum-volunteer.wav","script":"N: Listen to a volunteer coordinator at a museum.\\nCoordinator: Welcome and thank you for volunteering this weekend. Please arrive fifteen minutes before your shift to collect your name badge and leave bags in the staff room. Most of you will help visitors find the correct galleries. If you don’t know an answer, don’t guess — send the visitor to the information desk near the main entrance. And remember, food and drinks are not allowed in the exhibition rooms, so please finish them before your shift.\\nN: Now answer the questions.","questions":[{"stem":"What is the main purpose of the talk?","options":["To describe the museum’s history.","To explain weekend procedures for volunteers.","To sell tickets for a new exhibition.","To advertise paid jobs."],"correct":1,"explanation":"The coordinator explains arrival time, duties, and rules for volunteers."},{"stem":"What should volunteers do if they don’t know an answer?","options":["Guess to be helpful.","Call the manager.","Send the visitor to the information desk.","Ask another visitor."],"correct":2,"explanation":"Instruction is not to guess but to send visitors to the information desk."},{"stem":"What rule is mentioned about food and drinks?","options":["They can be taken into galleries if covered.","They are sold inside the galleries.","They are not allowed in exhibition rooms.","They are provided for volunteers."],"correct":2,"explanation":"Food and drinks are not allowed in exhibition rooms; finish them before the shift."}]},{"id":"listen_08_office","audioFile":"listening-L08-office-hybrid-policy.wav","script":"N: Listen to a manager talking to a team about a work policy.\\nManager: As you know, we’re moving to a hybrid model next month. You’ll work from home Monday and Friday, and be in the office Tuesday through Thursday. The idea is to keep focused work at home but have in-person time for planning and training. Please update the shared calendar by this Friday so we know when to book meeting rooms. If you have concerns about equipment at home, talk to HR this week.\\nTeam member: Will the office hours change?\\nManager: No, hours stay nine to five, but you can request flexible start times through HR.\\nN: Now answer the questions.","questions":[{"stem":"When will employees work from home under the new model?","options":["Every day.","Only on weekends.","Monday and Friday.","Tuesday through Thursday."],"correct":2,"explanation":"Manager says work from home Monday and Friday, in office Tuesday-Thursday."},{"stem":"What are employees asked to do by Friday?","options":["Buy new office furniture.","Update the shared calendar for room booking.","Submit vacation requests.","Choose a new team leader."],"correct":1,"explanation":"Update the shared calendar by Friday so they know when to book meeting rooms."},{"stem":"What can employees do if they need home equipment?","options":["Talk to HR this week.","Email the manager next month.","Bring equipment from the office without asking.","Buy it themselves and keep the receipt."],"correct":0,"explanation":"Manager says if you have concerns about equipment at home, talk to HR this week."}]},{"id":"listen_09_doctor","audioFile":"listening-L09-doctor-followup.wav","script":"N: Listen to a doctor talking to a patient during a follow-up visit.\\nDoctor: Your blood pressure is lower than last month — that’s good progress. It looks like the new medication is working. How are you feeling?\\nPatient: Better, but I still get a little dizzy in the mornings.\\nDoctor: That can be a side effect at first. Try taking the pill in the evening instead, and keep checking your pressure daily. If the dizziness continues for more than a week, call the clinic.\\nPatient: Should I still avoid salty foods?\\nDoctor: Yes, keep limiting salt and keep walking thirty minutes a day. Let’s meet again in two weeks.\\nN: Now answer the questions.","questions":[{"stem":"What positive change does the doctor mention?","options":["The patient’s blood pressure has decreased.","The patient no longer needs medication.","The patient’s weight has increased.","The patient’s dizziness has stopped."],"correct":0,"explanation":"Doctor says blood pressure is lower than last month — good progress, medication is working."},{"stem":"What does the doctor suggest about the medication?","options":["Take a higher dose in the morning.","Stop taking it for a week.","Try taking it in the evening.","Take it only when dizzy."],"correct":2,"explanation":"Doctor suggests trying the pill in the evening and monitoring for a week."},{"stem":"What should the patient continue to do?","options":["Eat more salty foods.","Limit salt and walk thirty minutes daily.","Stay in bed all day.","Come to the clinic every day."],"correct":1,"explanation":"Keep limiting salt and walking thirty minutes a day; return in two weeks."}]},{"id":"listen_10_bike","audioFile":"listening-L10-bike-rental-trails.wav","script":"N: Listen to a conversation in a bike rental shop.\\nAssistant: Are you renting for the city or for the trails?\\nCustomer: For the trails. My brother is visiting and we planned a ride for Saturday.\\nAssistant: Then I should tell you the hill trail is partly closed after last week’s heavy rain.\\nCustomer: Is there another route you recommend?\\nAssistant: The river route is open and it’s easier. I’d also suggest helmets and a repair kit.\\nCustomer: Do helmets come with the bikes?\\nAssistant: Yes, helmets are included, but the repair kit costs extra.\\nCustomer: Fine — we’ll take two bikes, two helmets, and one repair kit.\\nN: Now answer the questions.","questions":[{"stem":"Why does the assistant mention the hill trail?","options":["To warn that part of it is closed after rain.","To advertise a new trail.","To explain shop hours.","To ask for a deposit."],"correct":0,"explanation":"Assistant warns that the hill trail is partly closed after heavy rain."},{"stem":"Which route does the assistant recommend instead?","options":["The city route.","The hill route.","The river route.","The mountain route."],"correct":2,"explanation":"The river route is open and easier."},{"stem":"What will the customer rent?","options":["One bike and one helmet.","Two bikes, two helmets, and a repair kit.","Two bikes only.","Two bikes and one helmet without a kit."],"correct":1,"explanation":"Customer says two bikes, two helmets, and one repair kit (helmets included, kit extra)."}]}]}]`),s={modules:e},t=JSON.parse(`[{"id":"b2_reading_comprehension","title":"MET B2 Reading — Comprehension Passages","skill":"reading","levelRange":"B2","items":[{"id":"read_01","type":"read","passage":"Remote work has transformed the modern workplace. Studies show that employees who work from home at least part of the week report higher job satisfaction and lower stress levels. Companies benefit too — they save on office space and can hire talent from anywhere in the world. However, some managers worry about maintaining team cohesion and productivity. Research suggests that hybrid models, where employees split time between office and home, may offer the best of both worlds. The key challenge is ensuring that remote workers feel included in team decisions and have equal access to opportunities for advancement.","source":"Workplace Trends Report 2024","questions":[{"id":"read_01_q1","question":"What is the main advantage of remote work for employees?","options":["Higher salaries","Better equipment","Greater job satisfaction","More vacation days"],"correct":2,"explanation":"The passage states employees 'report higher job satisfaction and lower stress levels'."},{"id":"read_01_q2","question":"What concern do some managers have about remote work?","options":["Increased costs","Legal issues","Team cohesion and productivity","Customer complaints"],"correct":2,"explanation":"The passage mentions managers 'worry about maintaining team cohesion and productivity'."},{"id":"read_01_q3","question":"According to the passage, what may be the ideal arrangement?","options":["Fully remote work","Full-time office work","Hybrid models","Freelance contracts"],"correct":2,"explanation":"The passage states 'hybrid models... may offer the best of both worlds'."}]},{"id":"read_02","type":"read","passage":"Public libraries are evolving beyond their traditional role as book repositories. Many now offer free internet access, computer classes, language courses, and even tool-lending programs. In some cities, libraries have become community hubs where people can attend workshops, meet with career counselors, or participate in local history projects. This transformation reflects a broader understanding that libraries serve as equalizers — providing resources to people regardless of their income or background. Despite budget pressures, library usage has actually increased in many areas, particularly among job seekers and students who need quiet study spaces.","source":"Community Services Journal","questions":[{"id":"read_02_q1","question":"What does the passage say about modern libraries?","options":["They only lend books.","They offer a wide range of services.","They have closed due to budget cuts.","They charge fees for computer use."],"correct":1,"explanation":"The passage describes libraries offering 'free internet access, computer classes, language courses' and more."},{"id":"read_02_q2","question":"Why are libraries described as 'equalizers'?","options":["They charge the same fee to everyone.","They provide resources regardless of income.","They are located in equal numbers across cities.","They employ staff from diverse backgrounds."],"correct":1,"explanation":"Libraries 'provide resources to people regardless of their income or background'."},{"id":"read_02_q3","question":"What trend in library usage is mentioned?","options":["Usage has declined significantly.","Only elderly people use libraries.","Usage has increased in many areas.","Libraries are only used in rural areas."],"correct":2,"explanation":"The passage states 'library usage has actually increased in many areas'."}]},{"id":"read_03","type":"read","passage":"The four-day work week has gained attention as companies experiment with shorter schedules. A recent trial in the UK involved 61 companies and found that most maintained or improved productivity while reducing employee stress and burnout. Employees reported better work-life balance and fewer sick days. However, critics argue that the model may not work in all industries, particularly healthcare, retail, and hospitality, where continuous coverage is essential. Some experts also worry that压缩ed schedules could lead to longer daily hours, which might reduce the intended benefits. The debate continues as more organizations consider whether the benefits outweigh the practical challenges.","source":"Business Weekly","questions":[{"id":"read_03_q1","question":"What was the main finding of the UK trial?","options":["Productivity decreased significantly.","Most companies maintained or improved productivity.","Employee turnover doubled.","Customer satisfaction dropped."],"correct":1,"explanation":"The passage states 'most maintained or improved productivity while reducing employee stress'."},{"id":"read_03_q2","question":"What is one concern about the four-day work week?","options":["Employees want more hours.","It only works in small companies.","Some industries need continuous coverage.","It increases training costs."],"correct":2,"explanation":"Critics argue it may not work in 'healthcare, retail, and hospitality, where continuous coverage is essential'."},{"id":"read_03_q3","question":"What does the passage suggest about the debate?","options":["It has been settled in favor of the four-day week.","More evidence is needed.","The model will replace traditional schedules.","Only large corporations support it."],"correct":1,"explanation":"The passage ends with 'The debate continues as more organizations consider' the model."}]}]},{"id":"r10_reading_pack","moduleType":"reading_set","title":"Reading Pack R10 — Education & Work","skill":"reading","levelRange":"B2","items":[{"id":"r10-apprenticeships","type":"read","passage":"Learn While You Earn\\n\\nFor many school-leavers, university feels like the only path to a good career. Apprenticeships offer a different route: young people work for a real employer while studying toward a recognized qualification. Instead of paying tuition fees, apprentices earn a salary from the first month, and the employer usually covers the training costs.\\n\\nThe model works best when the classroom learning connects directly to daily tasks. An apprentice electrician, for example, may study circuit theory in the morning and install wiring in the afternoon. This combination helps knowledge stick, because every new idea is tested in practice the same week it is taught.\\n\\nApprenticeships are not an easy option. The workload is heavy, combining a full job with evening study, and some programs pay modest wages at the start. Still, for students who prefer doing over memorizing, the mix of income, experience, and a qualification without debt can be difficult to beat.","source":"Platform practice pack R10","questions":[{"id":"r10-apprenticeships-q1","stem":"What is one financial advantage of an apprenticeship mentioned in the passage?","question":"What is one financial advantage of an apprenticeship mentioned in the passage?","options":["Apprentices receive no pay during training.","Apprentices earn money while their training is usually paid for.","Apprentices study full-time before starting work.","Apprentices must pay their own tuition fees."],"correct":1,"explanation":"The first paragraph contrasts apprenticeships with university: apprentices earn a salary while employers cover training."},{"id":"r10-apprenticeships-q2","stem":"According to the passage, why does the combination of study and work help learning?","question":"According to the passage, why does the combination of study and work help learning?","options":["Trainees repeat the same task every day.","Classroom study happens only after two years of work.","New ideas from class are quickly tested in real tasks.","Theory exams replace all practical work."],"correct":2,"explanation":"The electrician example shows morning theory applied to afternoon wiring work in the same week."},{"id":"r10-apprenticeships-q3","stem":"What can be inferred about the writer's attitude toward apprenticeships?","question":"What can be inferred about the writer's attitude toward apprenticeships?","options":["It admits real difficulties alongside the benefits.","It claims every apprentice becomes wealthy quickly.","It argues university is always the better choice.","It ignores any negative side of apprenticeships."],"correct":0,"explanation":"The final paragraph lists heavy workload and modest starting wages as real difficulties, so the writer's view is balanced."}]},{"id":"r10-digital-textbooks","type":"read","passage":"Heavy Bags, Light Screens?\\n\\nMany schools are replacing printed textbooks with digital versions on tablets and laptops. One clear benefit is cost and weight: a single device can hold every book a student needs for the year, and updates can be added without printing thousands of new copies. For schools with limited budgets, this difference matters.\\n\\nHowever, teachers report mixed results. Some students read faster on paper and remember more of what which they read, possibly because physical pages make it easier to return to a difficult paragraph. Screens also bring distractions. Messages, games, and videos are only one tap away, and long reading sessions can cause tired eyes.\\n\\nThe most successful schools do not treat the choice as all or nothing. They use digital books for subjects that change often, such as technology and current events, while keeping printed books for long novels and exam preparation. The device is a tool, and like any tool, its value depends on how carefully it is used.","source":"Platform practice pack R10","questions":[{"id":"r10-digital-textbooks-q1","stem":"What is one benefit of digital textbooks mentioned in the passage?","question":"What is one benefit of digital textbooks mentioned in the passage?","options":["Digital books improve eyesight.","Digital books remove all distractions.","Digital books are always cheaper for families.","Digital books save weight and are easy to update."],"correct":3,"explanation":"The first paragraph names cost, weight, and easy updates as the benefits of digital books."},{"id":"r10-digital-textbooks-q2","stem":"Why might some students remember more when reading on paper?","question":"Why might some students remember more when reading on paper?","options":["Paper books are always free.","Paper pages make it easier to revisit hard sections.","Paper books update themselves automatically.","Paper books prevent all tiredness."],"correct":1,"explanation":"The passage says physical pages may help because students can easily return to a difficult paragraph."},{"id":"r10-digital-textbooks-q3","stem":"What approach does the writer recommend?","question":"What approach does the writer recommend?","options":["Ban all devices from schools.","Give every subject only digital books.","Mix formats depending on the subject.","Stop buying books of any kind."],"correct":2,"explanation":"The final paragraph recommends digital for fast-changing subjects and print for novels and exams."}]},{"id":"r10-feedback-that-works","type":"read","passage":"Beyond 'Good Job'\\n\\nMost students have received feedback that says little more than 'good job' or 'needs improvement.' These comments feel safe, but they give the learner almost nothing to act on. Effective feedback looks different: it points to one specific part of the work, explains what worked or failed there, and suggests a concrete next step.\\n\\nTiming matters as much as content. A comment on an essay returned three weeks later arrives when the student has already forgotten the thinking behind it. Short feedback given within a day or two usually changes the next piece of work more than a long report delivered late. Even two sentences are enough.\\n\\nStudents also need a chance to use the advice. Teachers who build ten minutes of revision time into the next lesson let learners apply the comment immediately, turning feedback from a final judgment into part of the learning process itself.","source":"Platform practice pack R10","questions":[{"id":"r10-feedback-that-works-q1","stem":"What is the problem with comments like 'good job'?","question":"What is the problem with comments like 'good job'?","options":["They give learners almost nothing specific to act on.","They are too long for students to read.","They always contain incorrect information.","They are never positive enough."],"correct":0,"explanation":"The first paragraph says vague comments give the learner almost nothing to act on."},{"id":"r10-feedback-that-works-q2","stem":"Why is late feedback less useful?","question":"Why is late feedback less useful?","options":["It is always too positive.","It focuses only on grammar.","It is written too quickly.","It arrives after students forget their thinking."],"correct":3,"explanation":"The passage states that late feedback arrives after the student has forgotten their thinking."},{"id":"r10-feedback-that-works-q3","stem":"What is the purpose of revision time in the next lesson?","question":"What is the purpose of revision time in the next lesson?","options":["It shortens every lesson.","It lets students apply advice right away.","It removes the need for teachers.","It replaces all homework."],"correct":1,"explanation":"The final paragraph says revision time lets learners apply the comment immediately."}]},{"id":"r10-teen-sleep","type":"read","passage":"Let Teenagers Sleep\\n\\nAsking a sixteen-year-old to solve algebra at half past seven in the morning ignores biology. During puberty, the body clock shifts later: teenagers naturally feel sleepy later at night and need to sleep later in the morning. A schedule that suited a ten-year-old can leave an older student permanently short of rest.\\n\\nThe effects go beyond yawning in class. Studies link short sleep in teenagers to weaker concentration, lower mood, and more frequent illness. Some school districts that moved start times later by even one hour reported better attendance and calmer morning lessons within a single term.\\n\\nChange is not simple. Bus timetables, parents' working hours, and after-school sports all depend on the current schedule. Still, the evidence points in one direction: when schools treat sleep as part of learning rather than an obstacle to it, students arrive more ready to learn.","source":"Platform practice pack R10","questions":[{"id":"r10-teen-sleep-q1","stem":"Why do early starts particularly affect teenagers?","question":"Why do early starts particularly affect teenagers?","options":["Teenagers dislike all school subjects.","Teenagers need less sleep than adults.","Teenagers' body clocks naturally shift later.","Teenagers prefer studying at dawn."],"correct":2,"explanation":"The first paragraph explains that puberty shifts the body clock later."},{"id":"r10-teen-sleep-q2","stem":"What effects of short sleep are mentioned?","question":"What effects of short sleep are mentioned?","options":["Weaker concentration and more illness.","Stronger memory and better vision.","Faster growth and more energy.","Improved appetite and hearing."],"correct":0,"explanation":"The second paragraph links short sleep to concentration, mood, and illness."},{"id":"r10-teen-sleep-q3","stem":"What makes changing school start times difficult?","question":"What makes changing school start times difficult?","options":["Students refuse to sleep earlier.","Teachers dislike morning lessons.","Sleep has no effect on learning.","Transport and family routines depend on school times."],"correct":3,"explanation":"The final paragraph says buses, parents' hours, and sports all depend on current schedules."}]},{"id":"r10-adult-language-learning","type":"read","passage":"It Is Not Too Late\\n\\nAdults who start learning a language often apologize for their age before the first lesson. Research offers encouragement: while children may master pronunciation more easily, adults learn grammar rules faster and bring stronger study habits. Motivation, not age, is usually the deciding factor.\\n\\nThe most common mistake is waiting too long to speak. Learners who spend months only on apps and word lists arrive at their first conversation unable to build a sentence under pressure. Short, regular speaking practice trains the mouth and the memory together. Even ten minutes describing your day aloud helps.\\n\\nConsistency beats intensity. Thirty focused minutes every day builds more lasting skill than a single exhausting weekend session. A learner who accepts small daily progress, forgives missed days, and keeps speaking from the start will usually surprise themselves within a year.","source":"Platform practice pack R10","questions":[{"id":"r10-adult-language-learning-q1","stem":"What advantage do adult learners have?","question":"What advantage do adult learners have?","options":["Adults memorize faster than children in every area.","Adults learn grammar faster and study more effectively.","Adults never need to practise speaking.","Adults should only learn with textbooks."],"correct":1,"explanation":"The first paragraph says adults learn grammar faster and have stronger study habits."},{"id":"r10-adult-language-learning-q2","stem":"What mistake does the writer warn against?","question":"What mistake does the writer warn against?","options":["Using language apps every day.","Studying grammar rules first.","Delaying speaking practice for months.","Describing your day aloud."],"correct":2,"explanation":"The passage says learners who delay speaking cannot build sentences under pressure."},{"id":"r10-adult-language-learning-q3","stem":"What does the writer recommend about study habits?","question":"What does the writer recommend about study habits?","options":["Daily focused practice beats occasional long sessions.","Weekend study is the only method that works.","Missing one day ruins all progress.","Speaking practice should be avoided."],"correct":0,"explanation":"The final paragraph states that daily focused minutes beat one exhausting weekend session."}]},{"id":"r10-four-day-week","type":"read","passage":"Four Days, Same Pay?\\n\\nSeveral large trials have tested a four-day working week with no cut in salary. The results surprised many managers: revenue stayed steady or rose, sick days fell, and most employees said they would not return to five days. With one extra day for rest and errands, people arrived on Monday with more energy.\\n\\nThe model demands discipline. Meetings get shorter and coffee breaks fewer; low-value tasks are simply dropped. Companies that failed usually failed here. They removed a working day without changing how the other four were used, so the same workload was squeezed into less time.\\n\\nA four-day week is not possible everywhere. Hospitals, restaurants, and emergency services must cover every day, so they experiment instead with shorter shifts or flexible rotas. The broader lesson still applies: many organizations discover they can achieve the same results in less time once they measure output instead of hours.","source":"Platform practice pack R10","questions":[{"id":"r10-four-day-week-q1","stem":"What did the trials generally find?","question":"What did the trials generally find?","options":["Revenue always collapsed.","Employees demanded a return to five days.","Sick days increased sharply.","Revenue held steady while wellbeing improved."],"correct":3,"explanation":"The first paragraph reports steady or rising revenue, fewer sick days, and higher energy."},{"id":"r10-four-day-week-q2","stem":"Why did some companies fail with the model?","question":"Why did some companies fail with the model?","options":["They paid employees too much.","They kept old work habits in fewer days.","They hired too many new managers.","They refused to hold any meetings."],"correct":1,"explanation":"The passage says failing companies removed a day without changing how the other four were used."},{"id":"r10-four-day-week-q3","stem":"How do hospitals and restaurants handle the idea?","question":"How do hospitals and restaurants handle the idea?","options":["They already work only three days.","Their employees dislike short weeks.","They must stay open daily, so they adapt differently.","They are banned from any experiments."],"correct":2,"explanation":"Hospitals and restaurants must cover every day, so they try shorter shifts or flexible rotas instead."}]},{"id":"r10-first-internship","type":"read","passage":"The First Step In\\n\\nA first internship can feel disappointingly ordinary: answering emails, organizing files, and watching experienced colleagues do the interesting work. Yet these small tasks serve a purpose. They teach the unspoken rules of professional life: how meetings run, how deadlines are tracked, and how colleagues ask for help. No classroom fully explains these.\\n\\nThe difference between a useful internship and a wasted summer is usually mentoring. Interns who meet weekly with a supervisor to review progress learn far more than those left alone with repetitive tasks. A good mentor explains not just what to do but why it matters to the team.\\n\\nPay remains controversial. Unpaid positions exclude students who cannot afford to work for free, while paid programs attract stronger applicants and treat interns as real contributors. Whatever the salary, the true test of an internship is simple: does the intern leave with skills and contacts they did not have before?","source":"Platform practice pack R10","questions":[{"id":"r10-first-internship-q1","stem":"What value do routine tasks have for interns?","question":"What value do routine tasks have for interns?","options":["Small tasks teach the unspoken rules of work.","Emails are the most important skill in any job.","Interns should avoid watching colleagues.","Filing is more valuable than mentoring."],"correct":0,"explanation":"The first paragraph says small tasks teach the unspoken rules of professional life."},{"id":"r10-first-internship-q2","stem":"What makes an internship useful rather than wasted?","question":"What makes an internship useful rather than wasted?","options":["Working completely alone.","Avoiding all feedback.","Regular mentoring and progress reviews.","Doing only the most exciting tasks."],"correct":2,"explanation":"Weekly supervisor meetings to review progress separate useful internships from wasted ones."},{"id":"r10-first-internship-q3","stem":"What is the true test of an internship?","question":"What is the true test of an internship?","options":["The size of the company.","The length of the lunch break.","The number of emails answered.","New skills and contacts gained."],"correct":3,"explanation":"The final paragraph asks whether the intern leaves with new skills and contacts."}]},{"id":"r10-job-interviews","type":"read","passage":"The Interview Is a Conversation\\n\\nMany candidates treat job interviews as exams with right and wrong answers. Stronger candidates treat them as professional conversations. Researching the company beforehand, its products, customers, and recent news, allows an applicant to connect their own experience to real problems the team faces.\\n\\nStories beat adjectives. Saying 'I am a great team player' convinces nobody, but describing a disagreement you helped resolve shows teamwork in action. The best interview stories follow a simple shape: the situation, the action you took, and the result. One clear example usually impresses more than five vague claims.\\n\\nGood interviews run both ways. Candidates who ask thoughtful questions about training, daily work, and how success is measured learn whether the job truly fits them. An interview that feels like a real discussion is often a sign of a workplace where communication works.","source":"Platform practice pack R10","questions":[{"id":"r10-job-interviews-q1","stem":"Why should candidates research the company?","question":"Why should candidates research the company?","options":["Memorizing the company's founding date.","Connecting your experience to the team's real problems.","Flattering every interviewer personally.","Asking for the highest possible salary first."],"correct":1,"explanation":"Researching products, customers, and news lets applicants connect experience to real problems."},{"id":"r10-job-interviews-q2","stem":"What does the writer say about interview stories?","question":"What does the writer say about interview stories?","options":["One clear example beats several vague claims.","Longer answers are always better.","Adjectives convince more than stories.","Results should never be mentioned."],"correct":0,"explanation":"The passage says one clear situation-action-result example beats five vague claims."},{"id":"r10-job-interviews-q3","stem":"Why should candidates ask their own questions?","question":"Why should candidates ask their own questions?","options":["It guarantees a job offer.","It shows the candidate is desperate.","It reveals whether the job truly fits.","It shortens the interview unfairly."],"correct":2,"explanation":"Asking about training, daily work, and success measures shows whether the job fits."}]},{"id":"r10-workplace-mentoring","type":"read","passage":"Someone Who Has Been There\\n\\nStarting a first job can feel like arriving in a country where you do not speak the language. A workplace mentor, an experienced colleague assigned to guide newcomers, shortens this difficult period. Mentors explain procedures, introduce key people, and warn beginners about common mistakes before they happen.\\n\\nThe relationship benefits both sides. New employees settle faster and make fewer expensive errors, while mentors often report that explaining their work forces them to organize their own knowledge more clearly. Some even discover leadership ability they had not suspected in themselves.\\n\\nEffective mentoring needs structure. Pairs who meet regularly with a simple agenda achieve more than those who only talk when problems appear. A short monthly conversation about goals, difficulties, and next steps keeps the relationship useful long after the nervous first weeks are over.","source":"Platform practice pack R10","questions":[{"id":"r10-workplace-mentoring-q1","stem":"What does a workplace mentor do?","question":"What does a workplace mentor do?","options":["They set salaries for newcomers.","They replace all formal training.","They evaluate beginners for dismissal.","They guide newcomers and warn about mistakes early."],"correct":3,"explanation":"Mentors explain procedures, introduce people, and warn about mistakes in advance."},{"id":"r10-workplace-mentoring-q2","stem":"How do mentors benefit?","question":"How do mentors benefit?","options":["Mentors receive automatic promotions.","Mentors clarify their own knowledge by explaining it.","Mentors no longer need to do their jobs.","Mentors avoid all responsibility for errors."],"correct":1,"explanation":"Explaining their work forces mentors to organize their own knowledge more clearly."},{"id":"r10-workplace-mentoring-q3","stem":"What makes mentoring effective?","question":"What makes mentoring effective?","options":["Regular meetings with a simple agenda.","Talking only when problems appear.","Ending contact after the first week.","Meeting without any plan or goals."],"correct":0,"explanation":"Regular meetings with a simple agenda beat only talking when problems appear."}]},{"id":"r10-career-change","type":"read","passage":"Starting Over at Thirty-Five\\n\\nChanging careers in your thirties can feel like throwing away a decade of effort. In practice, little is wasted: a teacher who becomes a trainer, or a nurse who moves into health technology, carries across communication skills, patience, and professional contacts. Experience transfers more often than people expect.\\n\\nThe practical barriers are real, however. Retraining usually means evening courses after full working days, and an entry-level salary in a new field may be lower than the old one. Successful changers plan for this gap by saving several months of expenses before resigning and by testing the new field first, through freelance projects, volunteering, or shadowing a professional for a week.\\n\\nThe deepest obstacle is often psychological. Admitting that a chosen path no longer fits can feel like failure, when it is really information. People who treat the move as a reversible, time-limited experiment adapt faster than those who demand a guarantee before the first step.","source":"Platform practice pack R10","questions":[{"id":"r10-career-change-q1","stem":"What does the passage say about past experience?","question":"What does the passage say about past experience?","options":["Previous experience is always completely useless.","Only young people can learn new skills.","Skills and contacts often transfer to the new field.","Employers never hire career changers."],"correct":2,"explanation":"The teacher and nurse examples show communication skills and contacts carrying across."},{"id":"r10-career-change-q2","stem":"How should career changers handle the practical barriers?","question":"How should career changers handle the practical barriers?","options":["Save money in advance and test the new field first.","Resign immediately without any plan.","Refuse all freelance or volunteer work.","Avoid talking to professionals in the field."],"correct":0,"explanation":"The passage recommends saving months of expenses and testing the field first."},{"id":"r10-career-change-q3","stem":"What mindset helps most?","question":"What mindset helps most?","options":["Wait for a guarantee before acting.","Treat the move as a reversible experiment.","Keep the decision secret from everyone.","Change fields every few months."],"correct":1,"explanation":"Treating the move as a reversible, time-limited experiment helps people adapt faster."}]}]}]`),n={modules:t},a=[{id:"b2_writing_short_answers",title:"MET B2 Writing — Short Answer Questions",skill:"writing",levelRange:"B2",items:[{id:"write_01",type:"short",prompt:"Write about a time you had to make an important decision. What did you consider before deciding?",rubric:"Should mention at least two factors, explain the outcome, and use past tenses accurately.",targetWords:120},{id:"write_02",type:"short",prompt:"Describe a place in your city that you think more tourists should visit. Why is it special?",rubric:"Should include specific details about the place and explain why it deserves more attention.",targetWords:120},{id:"write_03",type:"short",prompt:"What are the advantages and disadvantages of working from home? Give your opinion.",rubric:"Should present at least one advantage and one disadvantage with supporting reasons.",targetWords:130},{id:"write_04",type:"short",prompt:"Explain how regular exercise can improve mental health. Use specific examples.",rubric:"Should link physical activity to mental wellbeing with at least two concrete benefits.",targetWords:120},{id:"write_05",type:"short",prompt:"Do you think children should learn a foreign language from a young age? Why or why not?",rubric:"Should present a clear position with at least two supporting arguments.",targetWords:120}]}],i={modules:a},r=[],o=[{id:"b2_grammar_mcq",title:"MET B2 Grammar — Multiple Choice",skill:"grammar",levelRange:"B2",items:[{id:"gram_01",type:"mcq",question:"By the time we arrived, the concert ___.",options:["already started","had already started","has already started","was already starting"],correct:1,explanation:"Past perfect 'had started' is used for an action completed before another past action."},{id:"gram_02",type:"mcq",question:"She would have passed the exam if she ___ harder.",options:["studied","had studied","has studied","studies"],correct:1,explanation:"Third conditional requires past perfect in the if-clause."},{id:"gram_03",type:"mcq",question:"The report ___ by the team before the deadline.",options:["was completed","completed","has been completed","is completed"],correct:0,explanation:"Passive voice is needed because the report receives the action."},{id:"gram_04",type:"mcq",question:"I wish I ___ more time to travel last year.",options:["have","had","would have","having"],correct:1,explanation:"'Wish' + past simple expresses regret about a present or general situation."},{id:"gram_05",type:"mcq",question:"Neither the manager nor the employees ___ aware of the change.",options:["was","is","were","has been"],correct:2,explanation:"With 'neither...nor', the verb agrees with the nearest subject (employees = plural)."}]},{id:"b2_grammar_blanks",title:"MET B2 Grammar — Fill the Blank",skill:"grammar",levelRange:"B2",items:[{id:"gram_blank_01",type:"blank",template:"If I ___ (know) about the traffic, I would have left earlier.",blanks:["had known"],explanation:"Third conditional: 'if + past perfect, would have + past participle'."},{id:"gram_blank_02",type:"blank",template:"She has been working here ___ 2019.",blanks:["since"],explanation:"'Since' is used with a point in time; 'for' is used with a duration."},{id:"gram_blank_03",type:"blank",template:"The project is expected ___ (complete) by next month.",blanks:["to be completed"],explanation:"Passive infinitive: 'expected to be + past participle'."},{id:"gram_blank_04",type:"blank",template:"Not only ___ the report, but she also presented it.",blanks:["did she write"],explanation:"Negative inversion: when a negative phrase starts a clause, the verb is inverted."},{id:"gram_blank_05",type:"blank",template:"He suggested that we ___ (take) a different approach.",blanks:["take"],explanation:"After 'suggested that', use the base form of the verb (subjunctive)."}]}],l={modules:o};export{l as g,s as l,n as r,r as s,i as w};
